<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Report a Problem · CS3B</title><link rel="stylesheet" href="assets/style.css"><script src="assets/theme.js" defer></script></head><body>
<header class="top"><div><strong>CS3B : Bulletin</strong><span>2026 – 2027</span></div><nav><a href="./">Home</a><a href="officers">Officers</a><a href="report-a-problem">Report a problem</a></nav></header>
<main class="container narrow"><section class="hero small"><p class="eyebrow">CONTACT THE OFFICERS</p><h1>Report a problem</h1><p>Your message will be sent directly to the class officers.</p></section>
<form class="card form" action="https://formsubmit.co/alibangbanglawrencejohn_bscs@plmun.edu.ph" method="post"><input type="hidden" name="_subject" value="CS3B Bulletin problem report">
<label>Name<input name="name" maxlength="120" autocomplete="name" required></label>
<label>Details<textarea name="details" rows="8" maxlength="5000" required></textarea></label>
<label>Email<input type="email" name="email" maxlength="190" autocomplete="email" required></label>
<button class="primary" type="submit">Submit</button></form></main></body></html>
